import math

def norm_cdf(x):
    return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))

def bs_call(S, K, r, sigma, T):
    d1 = (math.log(S / K) + (r + sigma**2 / 2) * T) / (sigma * math.sqrt(T))
    d2 = d1 - sigma * math.sqrt(T)
    return S * norm_cdf(d1) - K * math.exp(-r * T) * norm_cdf(d2)

def implied_vol_call(price, S, K, r, T, lo=1e-4, hi=3.0):
    for _ in range(100):                    # bisection: robust, monotone in sigma
        mid = (lo + hi) / 2
        if bs_call(S, K, r, mid, T) > price:
            hi = mid
        else:
            lo = mid
    return (lo + hi) / 2

print(round(implied_vol_call(5.00, 100, 100, 0.0, 1.0), 4))   # ~0.1254
print(round(bs_call(100, 100, 0.0, 0.15, 1.0), 3))            # ~5.979 at sigma=15%
